    w = int(g.get("grid_width", 0) or 0)
    h = int(g.get("grid_height", 0) or 0)

    def pt(v):
        if isinstance(v, (list, tuple)) and len(v) == 2:
            return [int(v[0]), int(v[1])]
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return [int(v["x"]), int(v["y"])]
            if "col" in v and "row" in v:
                return [int(v["col"]), int(v["row"])]
        return None

    def lst(x):
        return x if isinstance(x, list) else ([] if x is None else [x])

    me = pt(g.get("self_position")) or [0, 0]
    opp = pt(g.get("opponent_position")) or [w - 1 if w else 0, h - 1 if h else 0]
    obs = set()
    for s in lst(g.get("obstacles")):
        p = pt(s)
        if p: obs.add((p[0], p[1]))
    best = None
    bd = 10 ** 9
    for r in lst(g.get("resources")):
        p = pt(r)
        if p:
            d = abs(p[0] - me[0]) + abs(p[1] - me[1])
            if d < bd:
                bd = d
                best = p
    cand = []
    if best:
        dx = 0 if best[0] == me[0] else (1 if best[0] > me[0] else -1)
        dy = 0 if best[1] == me[1] else (1 if best[1] > me[1] else -1)
        cand = [[dx, 0], [0, dy], [dx, dy], [dx, -dy], [-dx, dy], [1, 0], [-1, 0], [0, 1], [0, -1]]
    else:
        dx = 1 if me[0] <= opp[0] else -1
        dy = 1 if me[1] <= opp[1] else -1
        cand = [[dx, 0], [0, dy], [1, 0], [0, 1], [-1, 0], [0, -1], [dx, dy]]
    for d in cand:
        x = me[0] + d[0]
        y = me[1] + d[1]
        if -1 <= d[0] <= 1 and -1 <= d[1] <= 1 and (w == 0 or (0 <= x < w and 0 <= y < h)) and (x, y) not in obs:
            return [int(d[0]), int(d[1])]
    return [0, 0]

