def choose_move(observation):
    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def is_point(v):
        return (
            isinstance(v, (list, tuple))
            and len(v) == 2
            and is_num(v[0]) and is_num(v[1])
        ) or (
            isinstance(v, dict)
            and ((v.get("x") is not None and v.get("y") is not None) or (v.get("row") is not None and v.get("col") is not None))
        )

    def to_point(v):
        if isinstance(v, (list, tuple)) and len(v) == 2 and is_num(v[0]) and is_num(v[1]):
            return [v[0], v[1]]
        if isinstance(v, dict):
            if is_num(v.get("x")) and is_num(v.get("y")):
                return [v.get("x"), v.get("y")]
            if is_num(v.get("row")) and is_num(v.get("col")):
                return [v.get("col"), v.get("row")]
        return None

    def get_any(d, keys):
        if not isinstance(d, dict):
            return None
        for k in keys:
            if k in d:
                return d.get(k)
        return None

    def flatten_points(obj, out, limit=64):
        if len(out) >= limit:
            return
        if obj is None:
            return
        p = to_point(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                flatten_points(v, out, limit)
                if len(out) >= limit:
                    return
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                flatten_points(v, out, limit)
                if len(out) >= limit:
                    return

    obs = observation if isinstance(observation, dict) else {}

    # Self position
    self_candidates = [
        get_any(obs, ["agent_pos", "position", "pos", "loc", "location", "self_pos", "player_pos"]),
        get_any(obs, ["self"]),
        get_any(obs, ["agent"]),
    ]
    self_pos = None
    for cand in self_candidates:
        p = to_point(cand)
        if p is not None:
            self_pos = p
            break
        if isinstance(cand, dict):
            for kk in ["position", "pos", "loc", "location", "x", "y", "row", "col"]:
                pass
    if self_pos is None and isinstance(obs.get("agent"), dict):
        self_pos = to_point(obs.get("agent").get("pos")) or to_point(obs.get("agent").get("position"))
    if self_pos is None:
        return [0, 0]

    # Resource / target / enemy extraction
    good = []
    bad = []
    neutral = []

    for key in ["resources", "resource_positions", "food", "targets", "goals", "collectibles", "treasures", "cells", "territory", "frontier", "unclaimed"]:
        flatten_points(obs.get(key), good, 128)
    for key in ["enemies", "enemy_positions", "opponents", "opponent_positions", "hazards", "traps", "bombs", "threats"]:
        flatten_points(obs.get(key), bad, 128)

    # Sometimes observations store entities as list of dicts
    for key in ["entities", "objects", "actors"]:
        arr = obs.get(key)
        if isinstance(arr, (list, tuple)):
            for e in arr:
