                    p = to_point(e.get("pos")) or to_point(e.get("position")) or to_point(e)
                    if p is not None:
                        kind = str(e.get("type", e.get("kind", e.get("name", "")))).lower()
                        if any(w in kind for w in ["enemy", "opponent", "hazard", "trap", "bomb", "threat"]):
                            bad.append(p)
                        elif any(w in kind for w in ["resource", "food", "target", "goal", "treasure", "cell", "territory"]):
                            good.append(p)
                        else:
