    # Infer task bias
    task = str(get_any(obs, ["task", "mode", "game", "scenario", "name"]) or "").lower()
    resource_mode = "resource" in task or "collect" in task
    pursuit_mode = "pursuit" in task or "evasion" in task or "pursuit_evasion" in task
    territory_mode = "territory" in task or "control" in task or "territory_control" in task

    # If no explicit data, use any visible grid entries as goals
    if not good:
        for key in ["grid", "board", "map", "world", "state"]:
            g = obs.get(key)
            if isinstance(g, (list, tuple)):
                # collect coordinates of promising cells from a matrix if values are numeric/str
                for y, row in enumerate(g):
