                            good.append([x, y])
                        elif s in ("enemy", "opponent", "hazard", "trap"):
                            bad.append([x, y])

    # Distance helpers
    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign(x):
        return (x > 0) - (x < 0)

    # Choose primary objective
    target = None
    if good:
        best_d = None
        for p in good:
            d = manhattan(self_pos, p)
            if best_d is None or d < best_d:
